-- Staff usernames: first.surname, generated by the system, staff-only sign-in alias.
ALTER TABLE "StaffMembership" ADD COLUMN "username" TEXT;

-- Backfill existing staff with at least two name parts; collisions get a numeric suffix.
WITH base AS (
  SELECT id, "workspaceId",
    regexp_replace(lower(split_part(btrim("displayName"), ' ', 1)), '[^a-z]', '', 'g') || '.' ||
    regexp_replace(lower(regexp_replace(btrim("displayName"), '^.* ', '')), '[^a-z]', '', 'g') AS u,
    position(' ' in btrim("displayName")) > 0 AS two_parts,
    "createdAt"
  FROM "StaffMembership"
), ranked AS (
  SELECT id, u, row_number() OVER (PARTITION BY "workspaceId", u ORDER BY "createdAt", id) AS n
  FROM base WHERE two_parts AND u ~ '^[a-z]+\.[a-z]+$'
)
UPDATE "StaffMembership" s SET "username" = CASE WHEN r.n = 1 THEN r.u ELSE r.u || r.n END
FROM ranked r WHERE s.id = r.id;

CREATE UNIQUE INDEX "StaffMembership_workspaceId_username_key" ON "StaffMembership"("workspaceId", "username");
